#!/usr/bin/env node

// Simple test for CLI threshold parsing
// This mimics what the CLI does

function parseThresholds(thresholdStrings) {
  if (!thresholdStrings || thresholdStrings.length === 0) {
    return undefined;
  }

  const thresholds = {};
  for (const str of thresholdStrings) {
    const match = str.match(/^([a-z_]+)=([0-9.]+)$/);
    if (!match) {
      throw new Error(`Malformed threshold: ${str}. Expected format: <metric>=<number>`);
    }
    const [, metric, valueStr] = match;
    const value = parseFloat(valueStr);
    if (Number.isNaN(value) || value < 0 || value > 1) {
      throw new Error(`Invalid threshold value for ${metric}: ${valueStr} is not between 0 and 1`);
    }
    thresholds[metric] = value;
  }
  return thresholds;
}

console.log('=== Test 1: Valid thresholds ===');
try {
  const result = parseThresholds(['exact_match=0.9', 'toxicity=0.95']);
  console.log('Parsed thresholds:', result);
} catch (error) {
  console.error('Error:', error.message);
}

console.log('\n=== Test 2: Single threshold ===');
try {
  const result = parseThresholds(['exact_match=0.5']);
  console.log('Parsed thresholds:', result);
} catch (error) {
  console.error('Error:', error.message);
}

