function evaluateThresholds(thresholds, evaluations) {
  if (!thresholds || Object.keys(thresholds).length === 0) {
    return { passed: true, thresholds: [] };
  }

  const results = [];
  let allPassed = true;

  for (const [metric, min] of Object.entries(thresholds)) {
    const evaluation = evaluations.find((m) => m.id === metric);
    const score = evaluation?.score ?? null;
    const passed = score !== null && score >= min;

    if (!passed) {
      allPassed = false;
    }

    results.push({
      metric,
      min,
      score,
      passed
    });
  }

  return {
    passed: allPassed,
    thresholds: results
  };
}

export function generateReport({
  evaluations,
  outputsPath,
  referencesPath,
  generatedAt = new Date().toISOString(),
  thresholds
}) {
  const totalSamples = evaluations.reduce((total, metric) => {
    if (typeof metric.total === 'number') return Math.max(total, metric.total);
    return total;
  }, 0);

  const thresholdResult = evaluateThresholds(thresholds, evaluations);

  return {
    metadata: {
      generatedAt,
      outputsPath,
      referencesPath,
      totalSamples
    },
    metrics: evaluations,
    passed: thresholdResult.passed,
    thresholds: thresholdResult.thresholds
  };
}

export function writeReport({
  report,
  format = 'json',
  reportPath,
  fs: fsModule = defaultFs
}) {
  const resolved = resolveReportPath(reportPath, format);
  const payload = format === 'markdown' ? toMarkdown(report) : toJson(report);
  fsModule.writeFileSync(resolved, payload, 'utf8');
  return resolved;
}

export {
  DEFAULT_METRICS,
  exactMatchMetric,
  toxicityMetric,
  lengthVarianceMetric,
  validateThresholds
};

