#!/usr/bin/env node

import fs from 'fs';
import path from 'path';
import os from 'os';
import {
  loadDataset,
  runEvaluations,
  generateReport,
  writeReport,
  validateThresholds
} from './packages/frai-core/src/eval/index.js';
import { toJson, toMarkdown } from './packages/frai-core/src/eval/reporters.js';

// Create temporary directory for test files
const tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), 'frai-test-'));

try {
  // Create test data
  const outputsPath = path.join(tmpDir, 'outputs.json');
  const referencesPath = path.join(tmpDir, 'references.json');

  fs.writeFileSync(outputsPath, JSON.stringify(['Hello', 'World', 'Test'], null, 2));
  fs.writeFileSync(referencesPath, JSON.stringify(['hello', 'world', 'test'], null, 2));

  console.log('=== Test 1: Load dataset ===');
  const dataset = loadDataset({ outputsPath, referencesPath });
  console.log('✓ Dataset loaded:', {
    outputCount: dataset.outputs.length,
    referenceCount: dataset.references.length
  });

  console.log('\n=== Test 2: Run evaluations ===');
  const evaluations = runEvaluations({
    outputs: dataset.outputs,
    references: dataset.references
  });
  console.log('✓ Evaluations completed:', {
    metricCount: evaluations.length,
    metrics: evaluations.map((m) => m.id)
  });

  console.log('\n=== Test 3: Validate thresholds (valid) ===');
  const errors = validateThresholds({ exact_match: 0.5 }, evaluations);
  console.log('✓ Validation passed:', errors === null);

  console.log('\n=== Test 4: Validate thresholds (unknown metric) ===');
  const errors2 = validateThresholds({ unknown_metric: 0.5 }, evaluations);
  console.log('✓ Validation failed as expected:', errors2 !== null);
  if (errors2) console.log('  Error:', errors2[0]);

  console.log('\n=== Test 5: Generate report with passing thresholds ===');
  const report1 = generateReport({
    evaluations,
    outputsPath,
    referencesPath,
    thresholds: { exact_match: 0.5 }
  });
  console.log('✓ Report generated:', {
    passed: report1.passed,
    thresholdCount: report1.thresholds.length,
    threshold: report1.thresholds[0]
  });

  console.log('\n=== Test 6: Generate report with failing thresholds ===');
  const report2 = generateReport({
    evaluations,
    outputsPath,
    referencesPath,
    thresholds: { exact_match: 0.99 }
  });
  console.log('✓ Report generated:', {
    passed: report2.passed,
    threshold: report2.thresholds[0]
  });

  console.log('\n=== Test 7: Generate report without thresholds ===');
  const report3 = generateReport({
    evaluations,
    outputsPath,
    referencesPath
  });
  console.log('✓ Report generated:', {
    thresholdCount: report3.thresholds.length,
    passed: report3.passed
  });

  console.log('\n=== Test 8: Write JSON report ===');
  const jsonPath = writeReport({
    report: report1,
    format: 'json',
    reportPath: path.join(tmpDir, 'report.json')
  });
  const jsonContent = JSON.parse(fs.readFileSync(jsonPath, 'utf8'));
  console.log('✓ JSON report written:', {
    hasMetadata: !!jsonContent.metadata,
    hasMetrics: !!jsonContent.metrics,
    hasPassed: 'passed' in jsonContent,
    hasThresholds: !!jsonContent.thresholds
  });

  console.log('\n=== Test 9: Write Markdown report ===');
  const mdPath = writeReport({
    report: report1,
    format: 'markdown',
    reportPath: path.join(tmpDir, 'report.md')
  });
  const mdContent = fs.readFileSync(mdPath, 'utf8');
  console.log('✓ Markdown report written:', {
    hasThresholdsSection: mdContent.includes('## Thresholds'),
    hasPASSStatus: mdContent.includes('PASS'),
    size: mdContent.length
  });

  console.log('\n=== Test 10: Markdown output for failing threshold ===');
  const mdPath2 = writeReport({
    report: report2,
    format: 'markdown',
    reportPath: path.join(tmpDir, 'report-fail.md')
  });
  const mdContent2 = fs.readFileSync(mdPath2, 'utf8');
  console.log('✓ Markdown report with failure:', {
    hasThresholdsSection: mdContent2.includes('## Thresholds'),
    hasFAILStatus: mdContent2.includes('FAIL')
  });

  console.log('\n✅ All integration tests passed!');
} finally {
  // Cleanup
  fs.rmSync(tmpDir, { recursive: true, force: true });
}

